diff --git a/ex.c b/ex.c
index 448d1ea5..4bd669a5 100644
--- a/ex.c
+++ b/ex.c
@@ -58,6 +58,17 @@ static char xirerr[] = "invalid range";
 static char xrnferr[] = "range not found";
 static char *xrerr;
 static void *xpret;		/* previous ex command return value */
+static int xasync;		/* run the next chain command in a thread */
+static struct exthread {	/* a chain command running in its own thread */
+	pthread_t id;
+	int idx, arg;
+	char *cmd;
+} **xthreads;			/* running async commands */
+static int xthreads_n;		/* number of running async commands */
+static int xthreads_sz;		/* allocated xthreads entries */
+static pthread_mutex_t xthreads_mtx = PTHREAD_MUTEX_INITIALIZER;
+static pthread_once_t xthreads_once = PTHREAD_ONCE_INIT;
+static pthread_key_t xthreads_key;	/* set in async command threads */
 static sbuf *xanchor;		/* anchored error status buffer */
 static int xqprop;		/* number of ex_exec levels :q propagates */
 
@@ -1601,6 +1612,18 @@ _EO(left,
 #undef EO
 #define EO(opt) {#opt, eo_##opt}
 
+static void ex_asyncwait(void);
+
+/* run the next chain command asynchronously, or wait for running ones */
+static void *ec_async(char *loc, char *cmd, char *arg)
+{
+	if (cmd[2] == '!')
+		ex_asyncwait();
+	else
+		xasync = 1;
+	return NULL;
+}
+
 /* commands & opts must be sorted longest of its kind topmost */
 static struct excmd {
 	char *name;
@@ -1627,6 +1650,8 @@ static struct excmd {
 	{"p", ec_print},
 	EO(ai),
 	{"ac", ec_setacreg},
+	{"as!", ec_async},
+	{"as", ec_async},
 	EO(err),
 	{"ef!", ec_fuzz},
 	{"ef", ec_fuzz},
@@ -1794,6 +1819,80 @@ static const char *ex_cmd(const char *src, sbuf *sb, int *idx)
 	return src;
 }
 
+static void ex_asynckey(void)
+{
+	pthread_key_create(&xthreads_key, NULL);
+}
+
+/* whether the caller is an async command thread */
+static int ex_asyncself(void)
+{
+	pthread_once(&xthreads_once, ex_asynckey);
+	return pthread_getspecific(xthreads_key) != NULL;
+}
+
+/* execute a parsed command and report its error status */
+static void ex_run(struct exthread *t)
+{
+	void *ret = excmds[t->idx].ec(t->cmd, excmds[t->idx].name, t->cmd + t->arg);
+	if (ret && ret != xuerr && xerr & 1)
+		ex_print(ret, msg_ft)
+}
+
+/* the thread entry of async commands */
+static void *ex_thread(void *arg)
+{
+	struct exthread *t = arg;
+	pthread_setspecific(xthreads_key, t);
+	ex_run(t);
+	return NULL;
+}
+
+static void ex_asyncpush(struct exthread *t)
+{
+	pthread_mutex_lock(&xthreads_mtx);
+	if (xthreads_n == xthreads_sz) {
+		xthreads_sz = xthreads_sz ? xthreads_sz * 2 : 8;
+		xthreads = erealloc(xthreads, xthreads_sz * sizeof(xthreads[0]));
+	}
+	xthreads[xthreads_n++] = t;
+	pthread_mutex_unlock(&xthreads_mtx);
+}
+
+/* run a parsed command in a new thread; async commands run theirs inline */
+static void ex_async(int idx, sbuf *sb, int arg)
+{
+	struct exthread *t = emalloc(sizeof(*t));
+	t->cmd = emalloc(sb->s_n + 1);
+	memcpy(t->cmd, sb->s, sb->s_n + 1);
+	t->idx = idx;
+	t->arg = arg;
+	if (ex_asyncself() || pthread_create(&t->id, NULL, ex_thread, t)) {
+		ex_run(t);
+		free(t->cmd);
+		free(t);
+	} else
+		ex_asyncpush(t);
+}
+
+/* wait for all async commands to finish; a no-op inside one of them */
+static void ex_asyncwait(void)
+{
+	struct exthread *t;
+	if (ex_asyncself())
+		return;
+	for (;;) {
+		pthread_mutex_lock(&xthreads_mtx);
+		t = xthreads_n ? xthreads[--xthreads_n] : NULL;
+		pthread_mutex_unlock(&xthreads_mtx);
+		if (!t)
+			break;
+		pthread_join(t->id, NULL);
+		free(t->cmd);
+		free(t);
+	}
+}
+
 /* execute a single ex command chain */
 void *ex_exec(const char *ln)
 {
@@ -1807,6 +1906,11 @@ void *ex_exec(const char *ln)
 	do {
 		sbuf_cut(sb, 0)
 		ln = ex_arg(ex_cmd(ln, sb, &idx), sb, &arg);
+		if (xasync) {
+			xasync = 0;
+			ex_async(idx, sb, arg);
+			continue;
+		}
 		ret = excmds[idx].ec(sb->s, excmds[idx].name, sb->s + arg);
 		xpret = ret;
 		if (ret && ret != xuerr && xerr & 1) {
@@ -1822,6 +1926,8 @@ void *ex_exec(const char *ln)
 			|| tmpxquit < -256)
 		restore(xquit)
 	if (!xexec_dep) {
+		xasync = 0;
+		ex_asyncwait();
 		if (xanchor) {
 			sbuf_free(xanchor)
 			xanchor = NULL;
